import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import AuthForm from '../components/AuthForm';
import API from '../api';

const parseError = (err) => {
  if (!err.response) return null;
  const detail = err.response?.data?.detail;
  if (!detail) return 'Something went wrong. Please try again.';
  if (typeof detail === 'string') return detail;
  if (Array.isArray(detail)) return detail.map(d => d.msg).join(', ');
  return 'Something went wrong. Please try again.';
};

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const RegisterPage = () => {
  const [email, setEmail] = React.useState('');
  const [password, setPassword] = React.useState('');
  const [displayName, setDisplayName] = React.useState('');
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [status, setStatus] = React.useState(null);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    setStatus(null);

    if (password.length < 8) {
      setError('Password must be at least 8 characters.');
      setLoading(false);
      return;
    }

    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        setStatus(attempt === 1 ? 'Registering account...' : `Starting up... retrying (${attempt}/3)`);
        // Fix 1: Send email, password, and display_name for registration
        await API.post('/auth/register', { email, password, display_name: displayName });

        setStatus('Account created. Signing in...');
        // Fix 2: Send email and password for login
        const loginRes = await API.post('/auth/login', { email, password });
        localStorage.setItem('access_token', loginRes.data.access_token); // CRITICAL REPAIR: 'token' -> 'access_token'
        if (loginRes.data.display_name) localStorage.setItem('display_name', loginRes.data.display_name);
        if (loginRes.data.user_id) localStorage.setItem('user_id', String(loginRes.data.user_id));
        if (loginRes.data.email) localStorage.setItem('user_email', loginRes.data.email);
        navigate('/dashboard');
        return;
      } catch (err) {
        const msg = parseError(err);
        if (msg) { setError(msg); setLoading(false); setStatus(null); return; }
        if (attempt < 3) { setStatus(`Backend starting up... retrying in 15s (${attempt}/3)`); await sleep(15000); }
      }
    }
    setError('Backend took too long. Wait 30 seconds then try again.');
    setLoading(false);
    setStatus(null);
  };

  const gradient = 'from-indigo-500 to-violet-500';
  const primaryName = 'indigo';

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center p-4 relative overflow-hidden">
      <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
        <div className={`absolute -top-24 -right-24 w-96 h-96 rounded-full bg-gradient-to-br ${gradient} opacity-20 dark:opacity-10 blur-3xl`} />
        <div className={`absolute bottom-0 left-1/4 w-72 h-72 rounded-full bg-gradient-to-br ${gradient} opacity-10 dark:opacity-[0.07] blur-3xl`} />
      </div>

      <AuthForm
        title="Create your account"
        onSubmit={handleSubmit}
        error={error}
        loading={loading}
        status={status}
        gradient={gradient}
        primaryName={primaryName}
      >
        <AuthForm.Input
          label="Email"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="you@example.com"
          required
        />
        <AuthForm.Input
          label="Display Name"
          type="text"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          placeholder="Your Name"
          required
        />
        <AuthForm.Input
          label="Password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Minimum 8 characters"
          required
        />
        <AuthForm.Button type="submit" disabled={loading}>
          Register
        </AuthForm.Button>
        <p className="text-center text-sm text-slate-600 dark:text-slate-400 mt-4">
          Already have an account?{' '}
          <Link to="/login" className={`font-medium text-${primaryName}-600 hover:text-${primaryName}-500 dark:text-${primaryName}-400 dark:hover:text-${primaryName}-300`}>
            Log in
          </Link>
        </p>
      </AuthForm>
    </div>
  );
};

export default RegisterPage;

