                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                  )}
                </button>
                <span className={`text-slate-800 dark:text-white ${task.done ? 'line-through text-slate-400 dark:text-slate-500' : ''}`}>
