from fastapi import APIRouter, Depends, HTTPException, Query, Path, Response, status
from sqlalchemy.orm import Session
from typing import Optional
from app.database import get_db
from app.utils.auth import get_current_user
from app.models.products import Products
from app.models.categories import Category
from app.schemas.product import ProductCreate

product_router = APIRouter()


def _product_to_dict(product: Products) -> dict:
    return {
        "id": product.id,
        "name": product.name,
        "sku": product.sku,
        "category_id": product.category_id,
        "price": product.price,
        "description": getattr(product, "description", None),
        "current_stock": getattr(product, "current_stock", None),
    }


@product_router.get("/products", response_model=dict)
def list_products(
    limit: int = Query(50, ge=1, le=500),
    offset: int = Query(0, ge=0),
    name: Optional[str] = Query(None, min_length=1),
    sku: Optional[str] = Query(None, min_length=1),
    category_id: Optional[int] = Query(None),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    query = db.query(Products)
    if name:
        query = query.filter(Products.name.ilike(f"%{name}%"))
    if sku:
        query = query.filter(Products.sku.ilike(f"%{sku}%"))
    if category_id:
        query = query.filter(Products.category_id == category_id)
    total = query.count()
    products = query.offset(offset).limit(limit).all()
    items = [_product_to_dict(p) for p in products]
    return {"items": items, "total": total}


@product_router.get("/products/{product_id}", response_model=dict)
def get_product(
    product_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    product = db.query(Products).filter(Products.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Not found")
    return _product_to_dict(product)


@product_router.post("/products", status_code=status.HTTP_201_CREATED, response_model=dict)
def create_product(
    product_in: ProductCreate,
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    category = db.query(Category).filter(Category.id == product_in.category).first()
    if not category:
        raise HTTPException(status_code=400, detail="Category does not exist")
    if db.query(Products).filter(Products.sku == product_in.sku).first():
        raise HTTPException(status_code=400, detail="SKU already exists")
    new_product = Products(
        name=product_in.name,
        sku=product_in.sku,
        category_id=category.id,
        price=product_in.price,
        description=getattr(product_in, "description", None),
        current_stock=0,
    )
    db.add(new_product)
    db.commit()
    db.refresh(new_product)
    return _product_to_dict(new_product)


@product_router.put("/products/{product_id}", response_model=dict)
def replace_product(
    product_in: ProductCreate,
    product_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    product = db.query(Products).filter(Products.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Not found")
    category = db.query(Category).filter(Category.id == product_in.category).first()
    if not category:
        raise HTTPException(status_code=400, detail="Category does not exist")
    existing_sku = db.query(Products).filter(Products.sku == product_in.sku, Products.id != product_id).first()
    if existing_sku:
        raise HTTPException(status_code=400, detail="SKU already exists")
    product.name = product_in.name
    product.sku = product_in.sku
    product.category_id = category.id
    product.price = product_in.price
    product.description = getattr(product_in, "description", None)
    db.commit()
    db.refresh(product)
    return _product_to_dict(product)


@product_router.delete("/products/{product_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_product(
    product_id: int = Path(..., ge=1),
    db: Session = Depends(get_db),
    current_user: "User" = Depends(get_current_user),
):
    product = db.query(Products).filter(Products.id == product_id).first()
    if not product:
        raise HTTPException(status_code=404, detail="Not found")
    db.delete(product)
    db.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

